using ContosoUniversity.Data;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextHelper
    {
        public static SchoolContext CreateContext(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }
    }
}

using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        [Fact]
        public void FullName_ReturnsLastNameCommaFirstName()
        {
            var student = new Student { FirstMidName = "John", LastName = "Doe" };
            Assert.Equal("Doe, John", student.FullName);
        }

        [Fact]
        public void FullName_WithEmptyFirstName_ReturnsLastNameCommaEmpty()
        {
            var student = new Student { FirstMidName = "", LastName = "Smith" };
            Assert.Equal("Smith, ", student.FullName);
        }

        [Fact]
        public void FullName_InstructorInheritsFromPerson()
        {
            var instructor = new Instructor { FirstMidName = "Jane", LastName = "Austen" };
            Assert.Equal("Austen, Jane", instructor.FullName);
        }

        [Fact]
        public void Student_IsSubclassOfPerson()
        {
            var student = new Student();
            Assert.IsAssignableFrom<Person>(student);
        }

        [Fact]
        public void Instructor_IsSubclassOfPerson()
        {
            var instructor = new Instructor();
            Assert.IsAssignableFrom<Person>(instructor);
        }
    }

    public class ErrorViewModelTests
    {
        [Fact]
        public void ShowRequestId_ReturnsFalse_WhenRequestIdIsNull()
        {
            var model = new ErrorViewModel { RequestId = null };
            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_ReturnsFalse_WhenRequestIdIsEmpty()
        {
            var model = new ErrorViewModel { RequestId = "" };
            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_ReturnsTrue_WhenRequestIdHasValue()
        {
            var model = new ErrorViewModel { RequestId = "abc-123" };
            Assert.True(model.ShowRequestId);
        }

        [Fact]
        public void RequestId_CanBeSetAndRetrieved()
        {
            var model = new ErrorViewModel { RequestId = "test-id-456" };
            Assert.Equal("test-id-456", model.RequestId);
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain the static queue to avoid cross-test interference
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain the static queue after each test
            while (_service.ReceiveNotification() != null) { }
            _service.Dispose();
        }

        [Fact]
        public void SendNotification_EnqueuesNotification_CanBeReceived()
        {
            _service.SendNotification("Student", "1", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.False(notification.IsRead);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithDisplayName_GeneratesCorrectMessage()
