using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextHelper.CreateContext();
            _controller = new NotificationsController(_context);
            // Drain any existing notifications from the static queue
            DrainNotifications();
        }

        public void Dispose()
        {
            DrainNotifications();
            _controller.Dispose();
            _context.Dispose();
        }

        private void DrainNotifications()
        {
            var svc = new ContosoUniversity.Services.NotificationService();
            while (svc.ReceiveNotification() != null) { }
            svc.Dispose();
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            var result = _controller.GetNotifications();

            Assert.IsType<JsonResult>(result);
            var value = result.Value;
            Assert.NotNull(value);

            // Use reflection to check dynamic properties
            var successProp = value.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(value)!);

            var countProp = value.GetType().GetProperty("count");
            Assert.NotNull(countProp);
            Assert.Equal(0, (int)countProp.GetValue(value)!);
        }

        [Fact]
        public void GetNotifications_WithItems_ReturnsNotifications()
        {
            // Enqueue some notifications
            var svc = new ContosoUniversity.Services.NotificationService();
            svc.SendNotification("Student", "1", "John", EntityOperation.CREATE);
            svc.SendNotification("Course", "2", "Chemistry", EntityOperation.UPDATE);
            svc.Dispose();

            var result = _controller.GetNotifications();

            Assert.IsType<JsonResult>(result);
            var value = result.Value!;

            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);

            var countProp = value.GetType().GetProperty("count");
            Assert.Equal(2, (int)countProp!.GetValue(value)!);

            var notifsProp = value.GetType().GetProperty("notifications");
            var notifs = (List<Notification>)notifsProp!.GetValue(value)!;
            Assert.Equal(2, notifs.Count);
            Assert.Equal("Student", notifs[0].EntityType);
            Assert.Equal("Course", notifs[1].EntityType);
        }

        [Fact]
        public void GetNotifications_Max10Limit()
        {
            var svc = new ContosoUniversity.Services.NotificationService();
            for (int i = 0; i < 15; i++)
            {
                svc.SendNotification("Student", i.ToString(), EntityOperation.CREATE);
            }
            svc.Dispose();

            var result = _controller.GetNotifications();

            var value = result.Value!;
            var countProp = value.GetType().GetProperty("count");
            Assert.Equal(10, (int)countProp!.GetValue(value)!);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            var result = _controller.MarkAsRead(1);

            Assert.IsType<JsonResult>(result);
            var value = result.Value!;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            var result = _controller.Index();
            Assert.IsType<ViewResult>(result);
        }
    }
}

