using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_SeedsStudents()
        {
            using var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Contains(context.Students, s => s.LastName == "Alexander");
            Assert.Contains(context.Students, s => s.LastName == "Alonso");
        }

        [Fact]
        public void Initialize_SeedsInstructors()
        {
            using var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(5, context.Instructors.Count());
            Assert.Contains(context.Instructors, i => i.LastName == "Abercrombie");
            Assert.Contains(context.Instructors, i => i.LastName == "Fakhouri");
        }

        [Fact]
        public void Initialize_SeedsDepartments()
        {
            using var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(4, context.Departments.Count());
            Assert.Contains(context.Departments, d => d.Name == "English");
            Assert.Contains(context.Departments, d => d.Name == "Mathematics");
            Assert.Contains(context.Departments, d => d.Name == "Engineering");
            Assert.Contains(context.Departments, d => d.Name == "Economics");
        }

        [Fact]
        public void Initialize_SeedsCourses()
        {
            using var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(7, context.Courses.Count());
            Assert.Contains(context.Courses, c => c.Title == "Chemistry");
            Assert.Contains(context.Courses, c => c.Title == "Calculus");
        }

        [Fact]
        public void Initialize_SeedsOfficeAssignments()
        {
            using var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(3, context.OfficeAssignments.Count());
        }

        [Fact]
        public void Initialize_SeedsCourseAssignments()
        {
            using var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(8, context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_SeedsEnrollments()
        {
            using var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(11, context.Enrollments.Count());
        }

        [Fact]
        public void Initialize_SkipsIfAlreadySeeded()
        {
            using var context = TestDbContextHelper.CreateContext();

            // Pre-seed a student
            context.Students.Add(new Student
            {
                FirstMidName = "Existing",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2020-01-01")
            });
            context.SaveChanges();

            // Call initialize - should skip since students exist
            DbInitializer.Initialize(context);

            // Should still only have the one pre-seeded student
            Assert.Single(context.Students);
            Assert.Equal("Existing", context.Students.First().FirstMidName);
        }

        [Fact]
        public void Initialize_SeedsDepartmentsWithCorrectBudgets()
        {
            using var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            var english = context.Departments.Single(d => d.Name == "English");
            Assert.Equal(350000, english.Budget);

            var math = context.Departments.Single(d => d.Name == "Mathematics");
            Assert.Equal(100000, math.Budget);
        }

        [Fact]
        public void Initialize_SeedsCoursesWithCorrectCredits()
        {
            using var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            var chemistry = context.Courses.Single(c => c.Title == "Chemistry");
            Assert.Equal(3, chemistry.Credits);

            var calculus = context.Courses.Single(c => c.Title == "Calculus");
            Assert.Equal(4, calculus.Credits);
        }

        [Fact]
        public void Initialize_EnrollmentsHaveCorrectGrades()
        {
            using var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            // Alexander's Chemistry enrollment should have grade A
            var alexanderChemistry = context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .First(e => e.Student.LastName == "Alexander" && e.Course.Title == "Chemistry");
            Assert.Equal(Grade.A, alexanderChemistry.Grade);
        }
    }
}

