    [Fact]
    public void Constructor_SetsPageIndexAndTotalPages()
    {
        var items = new List<string> { "a", "b" };
        var list = new PaginatedList<string>(items, 10, 2, 3);

        Assert.Equal(2, list.PageIndex);
        Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
        Assert.Equal(2, list.Count);
    }

    [Fact]
    public void HasNextPage_OnLastPage_ExactlyEqual_ReturnsFalse()
    {
        // PageIndex == TotalPages => HasNextPage should be false
        // This catches mutation of < to <=
        var source = Enumerable.Range(1, 10).AsQueryable();
        var result = PaginatedList<int>.Create(source, 2, 5); // 2 pages, on page 2
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(2, result.TotalPages);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void HasPreviousPage_OnPageTwo_ReturnsTrue_CatchesGeFlip()
    {
        // PageIndex=2 > 1 => true; mutation to >= would also be true
        // But PageIndex=1 > 1 => false; mutation to >= would be TRUE (caught by HasPreviousPage_FirstPage_ReturnsFalse)
        var source = Enumerable.Range(1, 10).AsQueryable();
        var result = PaginatedList<int>.Create(source, 2, 5);
        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void Create_SkipCalculation_PageOneStartsAtFirstItem()
    {
        // Verifies (pageIndex - 1) * pageSize = 0 for page 1
        // If mutated to pageIndex * pageSize, page 1 would skip items
        var source = new[] { 10, 20, 30, 40, 50 }.AsQueryable();
        var result = PaginatedList<int>.Create(source, 1, 3);
        Assert.Equal(10, result[0]);
        Assert.Equal(20, result[1]);
        Assert.Equal(30, result[2]);
    }

    [Fact]
    public void Create_SkipCalculation_PageTwoStartsCorrectly()
    {
        var source = new[] { 10, 20, 30, 40, 50 }.AsQueryable();
        var result = PaginatedList<int>.Create(source, 2, 3);
        Assert.Equal(2, result.Count);
        Assert.Equal(40, result[0]);
        Assert.Equal(50, result[1]);
    }
}

