[Fact]
public void Create_Post_FileExactly5MB_Succeeds()
{
    var dept = SeedDepartment();
    var course = new Course
    {
        CourseID = 2004,
        Title = "Boundary Test Course",
        Credits = 3,
        DepartmentID = dept.DepartmentID
    };

    var mockFile = new Mock<IFormFile>();
    mockFile.Setup(f => f.FileName).Returns("test.jpg");
    mockFile.Setup(f => f.Length).Returns(5 * 1024 * 1024); // Exactly 5MB — should be allowed

    // The file upload will fail with IOException since we use a fake path,
    // but it should pass the size check (not return "File size must be less than 5MB")
    var result = _controller.Create(course, mockFile.Object);

    // If file size check is >= instead of >, this would return "File size" error
    // Since we're at exactly 5MB with > check, it passes size validation
    // but fails on actual file I/O — which is fine, it proves the boundary
    var viewResult = Assert.IsType<ViewResult>(result);
    // Should NOT have the file size error
    Assert.False(_controller.ModelState.ContainsKey("teachingMaterialImage") &&
        _controller.ModelState["teachingMaterialImage"]!.Errors.Any(e => e.ErrorMessage.Contains("5MB")));
}

[Fact]
public void Create_Post_FileOneByteOver5MB_RejectsWithError()
{
    var dept = SeedDepartment();
    var course = new Course
    {
        CourseID = 2005,
        Title = "Over Limit Course",
        Credits = 3,
        DepartmentID = dept.DepartmentID
    };

    var mockFile = new Mock<IFormFile>();
    mockFile.Setup(f => f.FileName).Returns("test.png");
    mockFile.Setup(f => f.Length).Returns(5 * 1024 * 1024 + 1); // One byte over

    var result = _controller.Create(course, mockFile.Object);

    Assert.IsType<ViewResult>(result);
    Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
    Assert.Contains(errors, e => e.ErrorMessage.Contains("5MB"));
}

